from __future__ import absolute_import
from selenium.webdriver.common.by import By
from selenium.common.exceptions import NoSuchElementException
from taf.selenium.gnb.oam.coam.classical.common.common import LocalBasicPage


class DetailPanel(LocalBasicPage):
    _DETAIL_SECTION_MAIN_XPATH = "//div[@class='details-info-body']//table[@class='details-info-table']/.."
    _DETAILS_PANEL_XPATH = "//ui-button[contains(@a-on-click, 'showPanel()')]/button"
    _CHILD_DIV_XPATH = "./div"
    _ALL_TD_LABEL_XPATH = "./table//td"
    _PARAMETERS_NAV_XPATH = ('//div[contains(@class,"details-panel-content-inner-margin")]'
                             '//a[contains(text(), "Parameters")]')
    _INFO_NAV_XPATH = '//div[contains(@class,"details-panel-content-inner-margin")]//a[contains(text(), "Info")]'
    _PARAMETER_SECTIONS = '//div[@class="parameters-tab-panel-body"]/ul/li'

    def __init__(self, driver, download_checker=None):
        super(DetailPanel, self).__init__(driver, download_checker)

    def _get_section_info(self, elements):
        section_info = {}
        for index in range(len(elements) // 2):
            section_info.update({elements[2 * index].text.split(':')[0]: elements[2 * index + 1].text.strip()})
        return section_info

    def get_detail_info_table(self):
        """
        Get detail info on the detail panel
        :return: dict
        """
        self.click_enabled_element((By.XPATH, self._INFO_NAV_XPATH))

        info = dict()
        for elem in self.driver.find_elements_by_xpath(self._DETAIL_SECTION_MAIN_XPATH):
            try:
                section_name = elem.find_element_by_xpath(self._CHILD_DIV_XPATH).text
            except NoSuchElementException:
                section_name = None

            tds_element = elem.find_elements_by_xpath(self._ALL_TD_LABEL_XPATH)

            if section_name and not tds_element:
                info.update({section_name: {}})
            elif section_name and tds_element:
                info.update({section_name: self._get_section_info(tds_element)})
            else:
                info.update(self._get_section_info(tds_element))
        return info

    @staticmethod
    def _get_parameter_name(span_element):
        param_name_lists = span_element.find_elements_by_xpath(".//span[contains(@class,'parameter-name')]")
        return param_name_lists[0].text.strip() if param_name_lists else ''

    @staticmethod
    def _get_parameter_value(span_element):
        param_value_lists = span_element.find_elements_by_xpath(".//span[contains(@class,'parameter-value')]")
        return param_value_lists[0].text.strip() if param_value_lists else ''

    def _extract_ul_info(self, ul, result_dict):
        for li in ul.find_elements_by_xpath('./li'):
            self._extract_li_info(li, result_dict)

    def _extract_li_info(self, elem, result_dict):
        child_span_elements = elem.find_elements_by_xpath("./span")
        child_ul_elements = elem.find_elements_by_xpath("./ul")
        param = {}

        if child_span_elements and self._get_parameter_name(child_span_elements[0]):
            param_name = self._get_parameter_name(child_span_elements[0])

            if child_ul_elements:
                param[param_name] = {}
                self._extract_ul_info(child_ul_elements[0], param[param_name])

            else:
                param_value = self._get_parameter_value(child_span_elements[0])
                param = {param_name: param_value}

        elif child_ul_elements:
            self._extract_ul_info(child_ul_elements[0], param)

        result_dict.update(param)

    def get_parameters_info(self):
        self.click_enabled_element((By.XPATH, self._PARAMETERS_NAV_XPATH))
        parameters = {}
        for section_li in self.driver.find_elements_by_xpath(self._PARAMETER_SECTIONS):
            self._extract_li_info(section_li, parameters)
        return parameters

    def expand_details_panel(self):
        if self.element_exists((By.XPATH, self._DETAILS_PANEL_XPATH)):
            self.click_enabled_element((By.XPATH, self._DETAILS_PANEL_XPATH))
